const menuToggle=document.querySelector('.menu-toggle'),fullMenu=document.querySelector('#full-menu');
menuToggle.addEventListener('click',()=>{const expanded=menuToggle.getAttribute('aria-expanded')==='true';menuToggle.setAttribute('aria-expanded',String(!expanded));fullMenu.hidden=expanded;});
fullMenu.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{fullMenu.hidden=true;menuToggle.setAttribute('aria-expanded','false');}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!fullMenu.hidden){fullMenu.hidden=true;menuToggle.setAttribute('aria-expanded','false');menuToggle.focus();}});
const mark=document.querySelector('.live-mark'),reduced=matchMedia('(prefers-reduced-motion: reduce)');
const moods={team:'ОДНА КОМАНДА',character:'СВОЙ ХАРАКТЕР',motion:'ТОЛЬКО ВПЕРЁД'};
mark.querySelectorAll('button[data-mood]').forEach(button=>button.addEventListener('click',()=>{mark.dataset.mood=button.dataset.mood;document.querySelector('#mood-label').textContent=moods[button.dataset.mood];mark.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}));
mark.addEventListener('pointermove',e=>{if(reduced.matches||e.pointerType==='touch')return;const r=mark.getBoundingClientRect();mark.style.setProperty('--mx',((e.clientX-r.left)/r.width-.5)*13+'px');mark.style.setProperty('--my',((e.clientY-r.top)/r.height-.5)*9+'px');});
mark.addEventListener('pointerleave',()=>{mark.style.setProperty('--mx','0px');mark.style.setProperty('--my','0px');});
let pending=false;function progress(){document.querySelector('.read-progress').style.transform='scaleX('+(scrollY/Math.max(1,document.documentElement.scrollHeight-innerHeight))+')';pending=false;}
addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(progress);}},{passive:true});progress();
const dayData=[['Время узнавать новое','Здесь будут сведения об учебной части программы полного дня и подготовке домашних заданий.'],['Время двигаться','Здесь будут представлены спортивные занятия, доступные направления и условия участия.'],['Время быть вместе','Здесь будут описаны творческие занятия, командные проекты и совместный отдых.']];
const dayButtons=[...document.querySelectorAll('[data-day]')];
function selectDay(button){dayButtons.forEach(b=>{b.setAttribute('aria-selected',String(b===button));b.tabIndex=b===button?0:-1;});const i=Number(button.dataset.day),p=document.querySelector('#day-panel');p.setAttribute('aria-labelledby',button.id);p.querySelector('.day-number').textContent='0'+(i+1);p.querySelector('h3').textContent=dayData[i][0];p.querySelector('p').textContent=dayData[i][1];}
dayButtons.forEach((button,i)=>{button.addEventListener('click',()=>selectDay(button));button.addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;selectDay(dayButtons[n]);dayButtons[n].focus();});});
const dialog=document.querySelector('#detail-dialog'),content=dialog.querySelector('.dialog-content');let lastTrigger=null,galleryIndex=null;
function openDialog(html,trigger){lastTrigger=trigger;content.innerHTML=html;dialog.showModal();document.body.style.overflow='hidden';}
dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('close',()=>{document.body.style.overflow='';lastTrigger?.focus();galleryIndex=null;});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
const galleryTitles=['До первого свистка','Всё начинается здесь','Ещё одна попытка'];
function galleryHTML(){return '<img class="dialog-photo" src="assets/court.png" alt="Иллюстрация концепции: кроссовки и баскетбольный мяч на площадке"><span class="dialog-label">ФОТОГАЛЕРЕЯ / ВИЗУАЛЬНЫЙ ПРИМЕР</span><h2>'+galleryTitles[galleryIndex]+'</h2><p>Так будет выглядеть история события: фотография, подпись и переход между кадрами. Это иллюстрация концепции, а не фотография школы.</p><div class="gallery-controls"><button data-gallery-step="-1">Предыдущий кадр</button><span>'+(galleryIndex+1)+' / 3</span><button data-gallery-step="1">Следующий кадр</button></div>';}
document.querySelectorAll('[data-gallery]').forEach(button=>button.addEventListener('click',()=>{galleryIndex=Number(button.dataset.gallery);openDialog(galleryHTML(),button);}));
content.addEventListener('click',e=>{const control=e.target.closest('[data-gallery-step]');if(control){const direction=control.dataset.galleryStep;galleryIndex=(galleryIndex+Number(direction)+3)%3;content.innerHTML=galleryHTML();content.querySelector('[data-gallery-step="'+direction+'"]').focus();}});
dialog.addEventListener('keydown',e=>{if(galleryIndex!==null&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();galleryIndex=(galleryIndex+(e.key==='ArrowRight'?1:2))%3;content.innerHTML=galleryHTML();dialog.querySelector('.dialog-close').focus();}});
const details={first:['Первый старт','Первая история может быть посвящена ученику, который решился впервые выступить на соревнованиях. Здесь появятся его слова, фотографии и впечатления.'],progress:['Личный прогресс','Здесь можно показать путь участника: с чего он начинал, над чем работал и какого результата достиг. Все результаты будут добавлены после подтверждения школой.'],team:['Командная победа','Здесь будет история реального соревнования: состав команды, подготовка, результат и фотографии. Данные будут добавлены школой.']};
document.querySelectorAll('[data-detail]').forEach(button=>button.addEventListener('click',()=>{const d=details[button.dataset.detail];openDialog('<span class="dialog-label">ФОРМАТ ИСТОРИИ / НАШИ ДОСТИЖЕНИЯ</span><h2>'+d[0]+'</h2><p>'+d[1]+'</p>',button);}));
const persons=[['Руководитель клуба','В карточке руководителя можно разместить имя, портрет, задачи в клубе и короткое обращение к ученикам.'],['Педагог-наставник','В карточке наставника можно рассказать о спортивном направлении, подходе к занятиям и поддержке новичков.'],['Ученический актив','Здесь будут представлены участники ученического совета: их инициативы, роли и идеи для жизни клуба.']];
document.querySelectorAll('[data-person]').forEach(button=>button.addEventListener('click',()=>{const d=persons[Number(button.dataset.person)];openDialog('<span class="dialog-label">СОВЕТ КЛУБА / ПРИМЕР КАРТОЧКИ</span><h2>'+d[0]+'</h2><p>'+d[1]+'</p>',button);}));
document.querySelectorAll('[data-doc]').forEach(button=>button.addEventListener('click',()=>openDialog('<span class="dialog-label">ДОКУМЕНТЫ КЛУБА</span><h2>'+button.dataset.doc+'</h2><p>В готовой версии здесь откроется официальный документ с возможностью прочитать его и скачать.</p><p class="document-state">Файл пока не добавлен. Это демонстрация интерфейса.</p>',button)));
if('IntersectionObserver' in window&&!reduced.matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('revealed');observer.unobserve(entry.target);}}),{threshold:.06});document.querySelectorAll('.split,.section-title,.council-grid').forEach(el=>{el.classList.add('reveal-ready');observer.observe(el);});}